#include <stdio.h>

enum { OTHER, LOAD, ALU };
#define N 7   /* 6 real instructions + halt */

typedef struct { int op, dst, src1, src2; } Instr;

int main(void) {
    /* classic CS:APP load/use demo; registers: rdx=0 rcx=1 rax=2 rbx=3 */
    Instr prog[N] = {
        { ALU,   0, -1, -1 },  /* irmovq $128,%rdx       */
        { ALU,   1, -1, -1 },  /* irmovq $3,%rcx         */
        { OTHER,-1,  1,  0 },  /* rmmovq %rcx,0(%rdx)    */
        { ALU,   3, -1, -1 },  /* irmovq $10,%rbx        */
        { LOAD,  2,  0, -1 },  /* mrmovq 0(%rdx),%rax    */
        { ALU,   2,  3,  2 },  /* addq %rbx,%rax         */
        { OTHER,-1, -1, -1 },  /* halt                   */
    };

    int stage[5]; for (int i = 0; i < 5; i++) stage[i] = -1; /* F D E M W */
    int next_fetch = 0, cycle = 0;
    const char *names[5] = {"F","D","E","M","W"};

    while (stage[4] != N - 1) {
        cycle++;
        int E = stage[2], D = stage[1];
        int load_use = (E != -1 && D != -1 && prog[E].op == LOAD &&
                         (prog[E].dst == prog[D].src1 ||
                          prog[E].dst == prog[D].src2));

        int next[5];
        next[4] = stage[3];
        next[3] = stage[2];
        if (load_use) {
            next[2] = -1;             /* bubble into E */
            next[1] = stage[1];       /* D stalls      */
            next[0] = stage[0];       /* F stalls      */
        } else {
            next[2] = stage[1];
            next[1] = stage[0];
            next[0] = (next_fetch < N) ? next_fetch++ : -1;
        }
        for (int i = 0; i < 5; i++) stage[i] = next[i];

        printf("cycle %2d:", cycle);
        for (int i = 0; i < 5; i++)
            printf("  %s=%s", names[i], stage[i] == -1 ? "bubble" : "i");
        if (load_use) printf("   <-- load/use hazard: stall+bubble");
        printf("\n");
    }
    printf("total cycles: %d\n", cycle);
    return 0;
}
